where
ic.accept_node = #{platformCode}
and ivc.accept_node = #{platformCode}
and a.tenant_id = #{tenantId} AND a.industry_code = #{industryCode}
and (a.IF_ALL_RECEIVE='1' or a.RECEIVE_USERS LIKE concat('%',#{userId},'%'))  AND a.status = '1'

    AND a.notice_type = #{noticeType}


    and a.receive_end like concat('%',#{receiveEnd},'%')


${dataScope}
ORDER BY NOTICE_ID DESC


where a.status='1' AND a.receive_end like '%1%'
and ic.accept_node = #{platformCode}
and ivc.accept_node = #{platformCode}
AND current_timestamp between a.VALID_TIME and a.INVALID_TIME
AND NOT EXISTS (SELECT 1 FROM sys_notice_read Ar WHERE Ar.NOTICE_ID = a.NOTICE_ID AND Ar.USER_ID = #{userId})
AND (
    INSTR(a.RECEIVE_USERS, #{userId})>0
    OR INSTR(a.RECEIVE_DEPTS, #{deptId})>0
    OR (a.IF_ALL_RECEIVE = '1'
        AND (
            a.DEPT_ID =#{deptId}
            OR EXISTS ( SELECT 1 FROM SYS_DEPT D WHERE D.DEPT_ID=#{deptId} AND INSTR(D.ANCESTORS, a.DEPT_ID)>0 )
        )
    )
)
and PUBLISH_TIME is not null
ORDER BY a.PUBLISH_TIME DESC


where a.status='1' AND a.receive_end like '%2%'
and ic.accept_node = #{platformCode}
and ivc.accept_node = #{platformCode}
AND current_timestamp between a.VALID_TIME and a.INVALID_TIME
AND NOT EXISTS (SELECT 1 FROM sys_notice_read Ar WHERE Ar.NOTICE_ID = a.NOTICE_ID AND Ar.USER_ID = #{userId})
AND (
    INSTR(a.RECEIVE_USERS, #{userId})>0
    OR INSTR(a.RECEIVE_DEPTS, #{deptId})>0
    OR (a.IF_ALL_RECEIVE = '1'
        AND (
            a.DEPT_ID =#{deptId}
            OR EXISTS ( SELECT 1 FROM SYS_DEPT D WHERE D.DEPT_ID=#{deptId} AND INSTR(D.ANCESTORS, a.DEPT_ID)>0 )
        )
    )
)
and PUBLISH_TIME is not null
ORDER BY a.PUBLISH_TIME DESC

