update sys_notice
notice_title = #{noticeTitle}, notice_type = #{noticeType}, notice_content = #{noticeContent}, status = #{status}, update_by = #{updateBy}, valid_time = #{validTime}, publish_time = #{publishTime}, invalid_time = #{inValidTime}, IF_ALL_RECEIVE = #{ifAllReceive}, RECEIVE_DEPTS = #{receiveDepts}, RECEIVE_ROLES = #{receiveRoles}, RECEIVE_USERS = #{receiveUsers}, notice_banner = #{noticeBanner}, tenant_id = #{tenantId}, receive_end = #{receiveEnd}, update_time = #{updateTime}
where notice_id = #{noticeId}

mapper.insert:
INSERT INTO sys_notice_read ( notice_id, user_id, create_time ) SELECT NOTICE_ID, #{userId}, CURRENT_TIMESTAMP FROM sys_notice T WHERE T.status='1' AND T.receive_end like '%2%'
and T.NOTICE_TYPE = #{noticeType}
AND NOT EXISTS ( SELECT 1 FROM sys_notice_read A WHERE A.NOTICE_ID = T.NOTICE_ID AND A.USER_ID = #{userId}) AND ( INSTR( T.RECEIVE_USERS, #{userId})>0 OR INSTR( T.RECEIVE_DEPTS, #{deptId})>0 OR ( T.IF_ALL_RECEIVE = '1' AND ( T.DEPT_ID = #{deptId} OR EXISTS ( SELECT 1 FROM SYS_DEPT D WHERE D.DEPT_ID = #{deptId} AND INSTR(D.ANCESTORS, T.DEPT_ID) > 0 ) ) ) )
